// Notion blocks -> Markdown. See PUBLISHING.md §4a.
const blocks = $json.results || [];
function rt(arr = []) {
  return arr.map((t) => {
    let s = t.plain_text ?? (t.text && t.text.content) ?? "";
    const a = t.annotations || {};
    if (a.code) s = "`" + s + "`";
    if (a.bold) s = "**" + s + "**";
    if (a.italic) s = "*" + s + "*";
    if (a.strikethrough) s = "~~" + s + "~~";
    const href = t.href || (t.text && t.text.link && t.text.link.url);
    if (href) s = "[" + s + "](" + href + ")";
    return s;
  }).join("");
}
const lines = [];
for (const b of blocks) {
  const t = b.type;
  const d = b[t] || {};
  switch (t) {
    case "heading_1": lines.push("# " + rt(d.rich_text), ""); break;
    case "heading_2": lines.push("## " + rt(d.rich_text), ""); break;
    case "heading_3": lines.push("### " + rt(d.rich_text), ""); break;
    case "paragraph": lines.push(rt(d.rich_text), ""); break;
    case "bulleted_list_item": lines.push("- " + rt(d.rich_text)); break;
    case "numbered_list_item": lines.push("1. " + rt(d.rich_text)); break;
    case "to_do": lines.push("- [" + (d.checked ? "x" : " ") + "] " + rt(d.rich_text)); break;
    case "quote": lines.push("> " + rt(d.rich_text), ""); break;
    case "code": lines.push("```" + (d.language || ""), rt(d.rich_text), "```", ""); break;
    case "divider": lines.push("---", ""); break;
    default: if (d.rich_text) lines.push(rt(d.rich_text), "");
  }
}
const markdown = lines.join("\n").replace(/\n{3,}/g, "\n\n").trim() + "\n";
return { markdown };

