// Assemble front matter + path. See PUBLISHING.md §4c.
const resp = $json;
const orig = $('Blocks to Markdown').item.json.markdown;
let proofed = (resp.message && resp.message.content) || "";
proofed = proofed.replace(/<think>[\s\S]*?<\/think>/gi, "").trim();
if (!proofed) proofed = orig;
proofed = proofed.trimEnd() + "\n";
const page = $('Notion: Get Database Pages').item.json;
const P = page.properties;
const title = P.Title.title.map((t) => t.plain_text).join("");
const sectionLabel = (P.Section.select && P.Section.select.name) || "Misc";
const tags = (P.Tags.multi_select || []).map((t) => t.name);
const description = (P.Description.rich_text || []).map((t) => t.plain_text).join("");
const slugProp = ((P.Slug && P.Slug.rich_text) || []).map((t) => t.plain_text).join("").trim();
const date = (P["Publish date"] && P["Publish date"].date && P["Publish date"].date.start) || new Date().toISOString().slice(0, 10);
const folderMap = { "Security": "security", "CTFs": "ctfs", "Home lab": "homelab", "Misc": "misc" };
const section = folderMap[sectionLabel] || "misc";
const slug = (slugProp || title).toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/(^-|-$)/g, "");
const fm = [
  "---",
  "title: " + JSON.stringify(title),
  "date: " + date,
  "tags: [" + tags.map((t) => JSON.stringify(t)).join(", ") + "]",
  "section: " + section,
  "description: " + JSON.stringify(description),
  "---",
  ""
].join("\n");
const fileContent = fm + proofed;
return {
  path: "content/" + section + "/" + slug + ".md",
  slug: slug,
  section: section,
  branch: "post-" + slug,
  commitMessage: "Add post: " + title,
  contentBase64: Buffer.from(fileContent, "utf8").toString("base64"),
  pageId: page.id
};
